#!/usr/bin/env node
// Config hook of the Release 1 scratch build (tools/accept/r1_build.py): runs the BASE1863 hook (which runs the unmodified generator tools/t0/config/gen.mjs and adds the
// immutable cache class for /tiles1863/*), then removes the one thing the acceptance copy audit (check 8) rejects in the shipped configuration files: the first comment line
// of _headers, _redirects and netlify.toml names the build tool ("Generated by tools/t0/config/gen.mjs ... DO NOT EDIT").  Only that wording is replaced; every rule is untouched.
// config-manifest.json gets the new sha256 of _headers and _redirects.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const [dist, json] = process.argv.slice(2);
const r = spawnSync('node', [path.join(HERE, '..', 't0', 'base1863', 'config_hook.mjs'), dist, json], { encoding: 'utf8', env: process.env });
process.stdout.write(r.stdout || ''); process.stderr.write(r.stderr || '');
if (r.status !== 0) process.exit(r.status || 1);

const edits = [
  ['_headers', /^# Generated by tools\/t0\/config\/gen\.mjs for release (\S+) \(train (\S+), context ([^)]+)\)\.\s+DO NOT EDIT\./m, (m, rid, train, ctx) => `# Release ${rid} (${train}, ${ctx}).`],
  ['_redirects', /^# Generated by tools\/t0\/config\/gen\.mjs\.\s+DO NOT EDIT\.\s+First matching rule wins;/m, () => '# First matching rule wins;'],
  ['netlify.toml', /^# Generated by tools\/t0\/config\/gen\.mjs for release (\S+?)\.\s+DO NOT EDIT\./m, (m, rid) => `# Release ${rid}.`],
];
const mp = path.join(dist, '_ops', 'config-manifest.json');
const man = JSON.parse(fs.readFileSync(mp, 'utf8'));
for (const [f, re, fn] of edits) {
  const p = path.join(dist, f); let t = fs.readFileSync(p, 'utf8');
  if (!re.test(t)) { console.error(`r1 config: ${f}: the generator comment was not found (the generator changed?)`); process.exit(1); }
  t = t.replace(re, fn); fs.writeFileSync(p, t);
  if (man.sha256 && f in man.sha256) man.sha256[f] = crypto.createHash('sha256').update(t).digest('hex');
}
man.r1 = { note: 'tools/accept/r1_config_hook.mjs replaced the generator-name comment lines (copy audit)' };
fs.writeFileSync(mp, JSON.stringify(man, null, 2) + '\n');
console.log('r1 config: generator comments neutralised in _headers, _redirects, netlify.toml');
